    @Test
    fun realReceiptsAreAccepted() {
        receipts.forEach { event ->
            val receipt = assertNotNull(parseZapReceipt(event), event.id)
            assertEquals(event.pubkey, receipt.zapperPubkey)
            assertTrue(receipt.amountMsats > 0)
            assertEquals(event.tags.first { it[0] == "e" }[1], receipt.targetEventId)
        }
    }

    @Test
    fun realPostTotal() {
        val id = "436074db4c22e48e0a800169d5246daffd5c6444ce7570f89fe8a6c94ee77de9"
        val parsed = onePost.map { assertNotNull(parseZapReceipt(it), it.id) }
        val author = parsed.first().recipientPubkey
        val total = summarizeZaps(parsed, id, author, parsed.first().zapperPubkey)
        assertEquals(1_476_000, total.totalMsats)
        assertEquals(7, total.count)
    }
